227	    // Čas přichází zvenku, aby šel v testech zadat.
228	    public function cancel(string $reason, \DateTimeImmutable $when): void
229	    {
230	        // Opakované storno není chyba volajícího, jen už není co dělat.
231	        if ($this->status === OrderStatus::Cancelled) {
232	            return;
233	        }
234	
235	        // Storno je hrana grafu jako každá jiná: odeslanou ani doručenou
236	        // objednávku zpátky nevrátí.
237	        if (!$this->status->canTransitionTo(OrderStatus::Cancelled)) {
238	            throw InvalidOrderStateTransitionException::cannotTransition(
239	                $this->status->value,
240	                OrderStatus::Cancelled->value,
241	            );
242	        }
243	
244	        $this->status = OrderStatus::Cancelled;
245	        $this->cancellationNote = $reason === '' ? null : $reason;
